<?php
require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../config/database.php';require_role('dosen');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$decision=$_POST['decision']??'';if(in_array($decision,['Disetujui','Ditolak'],true)){$st=$pdo->prepare("UPDATE krs SET status=?,approved_by=?,updated_at=NOW() WHERE id=? AND status='Menunggu' AND mahasiswa_id IN (SELECT id FROM mahasiswa WHERE dosen_id=?)");$st->execute([$decision,current_user()['profile_id'],$id,current_user()['profile_id']]);flash($st->rowCount()?'success':'error',$st->rowCount()?'Keputusan berhasil disimpan.':'Pengajuan tidak ditemukan atau sudah diproses.');}redirect('persetujuan.php');}
$stmt=$pdo->prepare("SELECT k.*,m.nim,m.nama FROM krs k JOIN mahasiswa m ON m.id=k.mahasiswa_id WHERE m.dosen_id=? ORDER BY FIELD(k.status,'Menunggu','Disetujui','Ditolak'),k.created_at DESC");
$stmt->execute([current_user()['profile_id']]);
$rows=$stmt->fetchAll();
$stmtMhs=$pdo->prepare("SELECT nim,nama,prodi,angkatan FROM mahasiswa WHERE dosen_id=? ORDER BY nama ASC");
$stmtMhs->execute([current_user()['profile_id']]);
$mahasiswaBimbingan=$stmtMhs->fetchAll();
$pageTitle='Persetujuan KRS';$active='persetujuan';require __DIR__.'/../includes/header.php';
?>
<div class="page-heading"><div><div class="eyebrow">DOSEN WALI</div><h1>Persetujuan KRS</h1><p>Periksa pengajuan rencana studi mahasiswa bimbingan Anda.</p></div><div class="date-chip"><?= count(array_filter($rows,fn($r)=>$r['status']==='Menunggu')) ?> menunggu</div></div>
<div class="panel table-panel"><div class="table-toolbar"><div><h3>Mahasiswa Bimbingan</h3><p>Mahasiswa yang memilih Anda sebagai dosen wali saat registrasi.</p></div><span class="badge-soft"><?= count($mahasiswaBimbingan) ?> mahasiswa</span></div><div class="table-scroll"><table><thead><tr><th>NIM</th><th>Nama Mahasiswa</th><th>Program Studi</th><th>Angkatan</th></tr></thead><tbody><?php foreach($mahasiswaBimbingan as $m): ?><tr><td><?= e($m['nim']) ?></td><td><b><?= e($m['nama']) ?></b></td><td><?= e($m['prodi']) ?></td><td><?= (int)$m['angkatan'] ?></td></tr><?php endforeach; ?><?php if(!$mahasiswaBimbingan): ?><tr><td colspan="4" class="empty">Belum ada mahasiswa yang memilih Anda sebagai dosen wali.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="panel table-panel"><div class="table-toolbar"><div><h3>Daftar pengajuan</h3><p>Pengajuan KRS dari mahasiswa dalam data simulasi.</p></div><input class="search-input" placeholder="Cari mahasiswa..." oninput="filterTable(this,'approvalTable')"></div><div class="table-scroll"><table id="approvalTable"><thead><tr><th>Mahasiswa</th><th>Tanggal</th><th>Total SKS</th><th>Status</th><th>Keputusan</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><b><?= e($r['nama']) ?></b><small class="table-sub"><?= e($r['nim']) ?></small></td><td><?= e(date('d M Y',strtotime($r['created_at']))) ?></td><td><?= (int)$r['total_sks'] ?> SKS</td><td><span class="status <?= $r['status']==='Disetujui'?'approved':($r['status']==='Ditolak'?'rejected':'pending') ?>"><?= e($r['status']) ?></span></td><td><?php if($r['status']==='Menunggu'): ?><form class="inline-actions" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-mini btn-success" name="decision" value="Disetujui">Setujui</button><button class="btn btn-mini btn-danger" name="decision" value="Ditolak" onclick="return confirm('Tolak pengajuan ini?')">Tolak</button></form><?php else: ?><span class="muted">Telah diproses</span><?php endif; ?></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="5" class="empty">Belum ada pengajuan KRS.</td></tr><?php endif; ?>
</tbody></table></div></div>
